#!/usr/bin/perl
# ForbiddenItlwm build check. Reads this Mac's /usr/sbin/bluetoothd and its boot kernel collection in place, checks
# every Apple code layout that ForbiddenItlwm and BTLEAdvFixup rely on, and prints a short text report to paste into
# a GitHub discussion. Nothing is written, sent or uploaded, and the report carries no personal details (no host
# name, serial, user name or paths beyond the system files it reads).
#
#   perl check-my-mac.pl                 check this Mac
#   perl check-my-mac.pl --details FILE  also write the function names of the driver-relevant IO80211 tables to FILE
#                                        (Apple function names only), for judging a port to an unsupported macOS
#   perl check-my-mac.pl --bluetoothd FILE --kext FILE [--skywalk FILE] --family tahoe|sequoia|sonoma
#                                        check loose copies (IO80211Family / IOSkywalkFamily from a KDK, a bluetoothd)
#
# Needs only what every macOS ships: /usr/bin/perl, codesign, sw_vers, uname. Intel Macs only (x86_64 code).
use strict;
use warnings;
# Safety: a runaway recursion or loop stops the script instead of filling memory and swap.
use warnings FATAL => qw(recursion);
$SIG{ALRM} = sub { die "check-my-mac: stopped after 120 s, please report this\n" };
alarm 120;
use Digest::SHA qw(sha256_hex);
use MIME::Base64 qw(decode_base64);
use IO::Uncompress::Gunzip qw(gunzip $GunzipError);

my $VERSION = '2';

# BEGIN GENERATED PATTERNS (tools/gen_check_my_mac.py)
our @KNOWN = (
    ['tahoe', 'advertising', 'advertisingFind', '84c00f8438010000e80878f8ff488b084889c7ff91180900004189c6', '84c0909090909090e80878f8ff488b084889c7b801000000904189c6'],
    ['tahoe', 'scanning', 'scanningFind', '84c00f8438010000e8b27af8ff488b084889c7ff91a80900004189c6', '84c0909090909090e8b27af8ff488b084889c7b801000000904189c6'],
    ['tahoe', 'randomAddress', 'randomAddressFind', '83b83403000003772a31ffe83e6bceff', '83b83403000003772a90909090909090'],
    ['tahoe', 'extendedConnection', 'extendedConnectionFind', '0fb6bd5effffffe8cb9dcfff', 'bf010000009090e8cb9dcfff'],
    ['tahoe', 'dupFilter', 'dupFilterFind', '41f6c601750ef68518feffff0174054531f6eb0b41f6d64180e6014588750045887503', '41f6d64180e6014588750041c6450300eb11eb0b41f6d64180e6014588750045887503'],
    ['tahoe', 'advertising', 'advertisingFind2673', '84c00f8438010000e81878f8ff488b084889c7ff91180900004189c6', '84c0909090909090e81878f8ff488b084889c7b801000000904189c6'],
    ['tahoe', 'scanning', 'scanningFind2673', '84c00f8438010000e8c27af8ff488b084889c7ff91a80900004189c6', '84c0909090909090e8c27af8ff488b084889c7b801000000904189c6'],
    ['tahoe', 'randomAddress', 'randomAddressFind2673', '83b83403000003772a31ffe81e6cceff', '83b83403000003772a90909090909090'],
    ['tahoe', 'extendedConnection', 'extendedConnectionFind2673', '0fb6bd5effffffe8ab9ecfff', 'bf010000009090e8ab9ecfff'],
    ['tahoe', 'extendedConnection', 'extendedConnectionFind2672', '0fb6f8410fb6f4e886a0cfff0fb6bd76ffffffe81f3ad1ff488d05f91964004c8b20', '0fb6f8410fb6f4e886a0cfffbf010000009090e81f3ad1ff488d05f91964004c8b20'],
    ['sequoia', 'advertising', 'advertisingFind', '84c00f8438010000e8104cf9ff488b084889c7ff91c00700004189c6', '84c0909090909090e8104cf9ff488b084889c7b801000000904189c6'],
    ['sequoia', 'scanning', 'scanningFind', '84c00f8438010000e8ba4ef9ff488b084889c7ff91480800004189c6', '84c0909090909090e8ba4ef9ff488b084889c7b801000000904189c6'],
    ['sequoia', 'randomAddress', 'randomAddressFind', '83b8f802000003772331ffe859abd2ff', '83b8f802000003772390909090909090'],
    ['sequoia', 'extendedConnection', 'extendedConnectionFind', '0fb6bd5effffffe800cfd3ff', 'bf010000009090e800cfd3ff'],
    ['sequoia', 'dupFilter', 'dupFilterFind', 'f68500feffff01750df68528feffff01740431c0eb0b8b85f8fdffff340141880741884703', '8b85f8fdffff340141880741c6470300eb1331c0eb0b8b85f8fdffff340141880741884703'],
    ['sonoma', 'advertising', 'advertisingFind', '84c00f8434010000e88e7cfaff488b084889c7ff91000700004189c6', '84c0909090909090e88e7cfaff488b084889c7b801000000904189c6'],
    ['sonoma', 'scanning', 'scanningFind', '84c00f8434010000e8207ffaff488b084889c7ff91700700004189c6', '84c0909090909090e8207ffaff488b084889c7b801000000904189c6'],
    ['sonoma', 'randomAddress', 'randomAddressFind', '83b8c402000003772331ffe8fca4d6ff', '83b8c402000003772390909090909090'],
    ['sonoma', 'extendedConnection', 'extendedConnectionFind', '0fb6bd6effffffe8c8bfd7ff', 'bf010000009090e8c8bfd7ff'],
    ['sonoma', 'dupFilter', 'dupFilterFind', '80bd04feffff00750d80bd10feffff00740431c0eb0a8b8504feffff34018803884303', '8b8504feffff34018803c6430300eb13740431c0eb0a8b8504feffff34018803884303'],
);
# END GENERATED PATTERNS

# BEGIN GENERATED IMPORTS (tools/gen_check_my_mac.py --imports DIR)
our %IMPORTS = (
    tahoe => '',
    sequoia => '',
    sonoma => '',
);
# END GENERATED IMPORTS

# The IO80211 tables the driver's classes build on (ItlAWDLInterface, AirportItlwm, the infra interface).
my @TABLES = qw(__ZTV19IO80211AWDLProtocol __ZTV17IO80211Controller __ZTV20IO80211InfraProtocol __ZTV21IO80211InfraInterface
                __ZTV23IO80211SkywalkInterface __ZTV23IO80211VirtualInterface);

# What the driver uses on each macOS family (ForbiddenItlwm/AirportItlwmV2.cpp): the interface -> private -> peer
# manager chain, the peer manager state's RX and TX packet counters, and the IO80211AWDLProtocol slot count the driver's
# build guard expects (ForbiddenItlwm/AWDLBuildGuard.cpp; the vtable symbol also covers the 3-entry header).
my %EXPECT = (
    tahoe   => { priv => 0x120, pm => 0x28, rx => 0x79c, tx => 0x7b0, slots => 568 },
    sequoia => { priv => 0x110, pm => 0x28, rx => 0x78c, tx => 0x7a0, slots => 563 },
    sonoma  => { priv => 0x110, pm => 0x30, rx => 0x77c, tx => 0x790, slots => 547 },
);

my %opt = (bluetoothd => '/usr/sbin/bluetoothd', kc => '/System/Library/KernelCollections/BootKernelExtensions.kc');
while (@ARGV) {
    my $a = shift @ARGV;
    if ($a =~ /^--(bluetoothd|kc|kext|skywalk|family|details)$/ && @ARGV) { $opt{$1} = shift @ARGV; }
    else { die "usage: perl check-my-mac.pl [--details FILE] [--bluetoothd FILE] [--kc FILE | --kext FILE [--skywalk FILE]] [--family tahoe|sequoia|sonoma]\n"; }
}
my $live = !$opt{kext} && $opt{kc} eq '/System/Library/KernelCollections/BootKernelExtensions.kc';

my @out;
sub say_ { push @out, join('', @_); }
my (@problems, @todo);

# ---------------------------------------------------------------- this Mac
my ($osver, $osbuild, $kernel) = ('', '', '');
if ($live) {
    chomp($osver = `/usr/bin/sw_vers -productVersion 2>/dev/null` // '');
    chomp($osbuild = `/usr/bin/sw_vers -buildVersion 2>/dev/null` // '');
    chomp($kernel = `/usr/bin/uname -v 2>/dev/null` // '');
    $kernel =~ s/^.*?(root:)/$1/;   # keep only the xnu version, not the build date
}
my $family = $opt{family};
if (!$family) {
    $family = $osver =~ /^26\./ ? 'tahoe' : $osver =~ /^15\./ ? 'sequoia' : $osver =~ /^14\./ ? 'sonoma' : '';
}
say_("ForbiddenItlwm build check v$VERSION");
say_("macOS $osver ($osbuild), kernel $kernel, family " . ($family || 'unsupported')) if $live;
say_("loose files, family " . ($family || 'unknown')) unless $live;
push @problems, "this macOS version isn't one ForbiddenItlwm supports (Sonoma 14, Sequoia 15, Tahoe 26)" unless $family;
if ($live) {
    chomp(my $arch = `/usr/bin/uname -m 2>/dev/null` // '');
    push @problems, "not an Intel Mac ($arch)" if $arch ne 'x86_64';
}

# ---------------------------------------------------------------- Mach-O helpers
sub slurp { my ($p) = @_; open(my $f, '<:raw', $p) or return undef; local $/; my $d = <$f>; close $f; return $d; }
sub u32 { unpack('V', substr($_[0], $_[1], 4)) }
sub u64 { my ($lo, $hi) = unpack('VV', substr($_[0], $_[1], 8)); return $hi * 4294967296 + $lo; }

# The x86_64 slice of a universal file, or the file itself.
sub x86_slice {
    my ($d) = @_;
    return undef unless defined $d && length($d) > 32;
    my $magic = unpack('N', substr($d, 0, 4));
    if ($magic == 0xcafebabe) {
        my $n = unpack('N', substr($d, 4, 4));
        for my $i (0 .. $n - 1) {
            my ($cpu, $sub, $off, $size) = unpack('NNNN', substr($d, 8 + 20 * $i, 16));
            return substr($d, $off, $size) if $cpu == 0x01000007;
        }
        return undef;
    }
    return $d if unpack('V', substr($d, 0, 4)) == 0xfeedfacf;
    return undef;
}

# Load commands of the 64-bit Mach-O at $base: segments, symbol table and fileset entries.
sub macho {
    my ($d, $base) = @_;
    return undef unless u32($d, $base) == 0xfeedfacf;
    my $ncmds = u32($d, $base + 16);
    my $off = $base + 32;
    my %m = (segs => [], entries => []);
    for (1 .. $ncmds) {
        my ($cmd, $size) = (u32($d, $off), u32($d, $off + 4));
        if ($cmd == 0x19) {
            my $name = unpack('Z16', substr($d, $off + 8, 16));
            push @{$m{segs}}, [$name, u64($d, $off + 24), u64($d, $off + 32), u64($d, $off + 40), u64($d, $off + 48)];
        } elsif ($cmd == 0x2) {
            @m{qw(symoff nsyms stroff strsize)} = unpack('VVVV', substr($d, $off + 8, 16));
        } elsif ($cmd == 0xb) {
            @m{qw(extreloff nextrel)} = unpack('VV', substr($d, $off + 8 + 56, 8));
        } elsif ($cmd == 0x80000035) {
            my ($vm, $fo, $stroff) = (u64($d, $off + 8), u64($d, $off + 16), u32($d, $off + 24));
            push @{$m{entries}}, [unpack('Z*', substr($d, $off + $stroff, $size - $stroff)), $vm, $fo];
        }
        $off += $size;
    }
    return \%m;
}

sub va2off {
    my ($m, $va) = @_;
    for my $s (@{$m->{segs}}) { return $s->[3] + ($va - $s->[1]) if $va >= $s->[1] && $va < $s->[1] + $s->[2]; }
    return undef;
}

# Symbols whose names start with one of the wanted prefixes, plus every defined symbol address (for function sizes).
sub symbols {
    my ($d, $m, @want) = @_;
    my (%found, @addrs);
    return (\%found, \@addrs) unless $m->{nsyms};
    for my $i (0 .. $m->{nsyms} - 1) {
        my $e = $m->{symoff} + 16 * $i;
        my ($strx, $type) = (u32($d, $e), ord(substr($d, $e + 4, 1)));
        next if ($type & 0x0e) != 0x0e;   # defined in a section
        my $va = u64($d, $e + 8);
        push @addrs, $va;
        my $name = unpack('Z*', substr($d, $m->{stroff} + $strx, 256));
        for my $w (@want) { $found{$w} //= [$name, $va] if index($name, $w) == 0; }
    }
    @addrs = sort { $a <=> $b } @addrs;
    return (\%found, \@addrs);
}

sub fn_bytes {
    my ($d, $m, $addrs, $va) = @_;
    my $off = va2off($m, $va);
    return '' unless defined $off;
    my ($next) = grep { $_ > $va } @$addrs;
    my $len = defined $next ? $next - $va : 4096;
    $len = 8192 if $len > 8192;
    return substr($d, $off, $len);
}

sub has { my ($code, $hex) = @_; return index($code, pack('H*', $hex)) >= 0; }
# On an unsupported macOS there is nothing to compare against: values are only reported.
sub verdict { my ($ok) = @_; return !$family ? '(measured)' : ($ok ? 'OK' : 'DIFFERENT'); }

# Every defined symbol of an image: address -> name, and the set of names.
sub image_symbols {
    my ($d, $m, $byva, $names) = @_;
    return unless $m && $m->{nsyms};
    for my $i (0 .. $m->{nsyms} - 1) {
        my $e = $m->{symoff} + 16 * $i;
        my $type = ord(substr($d, $e + 4, 1));
        next if ($type & 0x0e) != 0x0e;
        my $name = unpack('Z*', substr($d, $m->{stroff} + u32($d, $e), 512));
        next if $name eq '';
        $byva->{u64($d, $e + 8)} //= $name;
        $names->{$name} = 1;
    }
}

# External relocations of a loose kext: offset from its first segment -> symbol name.
sub ext_relocs {
    my ($d, $m) = @_;
    my %r;
    return \%r unless $m->{nextrel};
    for my $i (0 .. $m->{nextrel} - 1) {
        my ($addr, $info) = unpack('lV', substr($d, $m->{extreloff} + 8 * $i, 8));
        next unless ($info >> 27) & 1;   # r_extern
        my $sym = $info & 0xffffff;
        my $e = $m->{symoff} + 16 * $sym;
        $r{$addr} = unpack('Z*', substr($d, $m->{stroff} + u32($d, $e), 512));
    }
    return \%r;
}

# The function names in a vtable: chained kernel-collection pointers (target = offset from the collection's lowest
# address), or, in a loose kext, plain local pointers and external relocations.
sub vtable_names {
    my ($d, $m, $va, $size, $byva, $kcbase, $relocs) = @_;
    my $off = va2off($m, $va);
    return () unless defined $off && $size >= 24;
    my @names;
    for my $k (2 .. int($size / 8) - 1) {   # skip offset-to-top and RTTI
        my $raw = u64($d, $off + 8 * $k);
        my $name;
        if (defined $kcbase) { $name = $raw ? $byva->{$kcbase + ($raw & 0x3fffffff)} : undef; }
        elsif ($raw) { $name = $byva->{$raw}; }
        else { $name = $relocs->{$va + 8 * $k - $m->{segs}[0][1]}; }
        push @names, $name // sprintf('?%x', $raw);
    }
    pop @names while @names && $names[-1] eq '?0';   # the zero terminator after the last slot
    return @names;
}

# ---------------------------------------------------------------- IO80211Family
my ($io, $iobase, $ioname);
if ($opt{kext}) {
    $io = x86_slice(slurp($opt{kext}));
    ($iobase, $ioname) = (0, $opt{kext});
} else {
    $io = slurp($opt{kc});
    if (defined $io) {
        my $kc = macho($io, 0);
        my ($entry) = grep { $_->[0] eq 'com.apple.iokit.IO80211Family' } @{$kc ? $kc->{entries} : []};
        $iobase = $entry ? $entry->[2] : undef;
    }
    $ioname = 'IO80211Family in the boot kernel collection';
}
say_('');
say_('[IO80211Family]');
my $iom = defined $io && defined $iobase ? macho($io, $iobase) : undef;
if (!$iom) {
    say_("  not readable ($ioname)");
    push @problems, "couldn't read IO80211Family";
} else {
    say_('  sha256 of __TEXT ' . substr(sha256_hex(do { my ($t) = grep { $_->[0] eq '__TEXT' } @{$iom->{segs}};
                                                    $t ? substr($io, $t->[3], $t->[4]) : '' }), 0, 16));
    my %fn = (
        pm    => '__ZN23IO80211SkywalkInterface14getPeerManagerEv',
        rx    => '__ZN18IO80211PeerManager11inputPacketEP20IO80211NetworkPacket',
        tx    => '__ZN18IO80211PeerManager14preQueuePacketEP6__mbuf',
        mi    => '__ZN22IO80211AWDLPeerManager22updatePrimaryPayloadMI',
        umi   => '__ZN22IO80211AWDLPeerManager13sendUnicastMI',
        rssi  => '__ZN22IO80211AWDLPeerManager32determineAndSetEdgeRssiThreshold',
        vt    => '__ZTV19IO80211AWDLProtocol',
    );
    my ($sym, $addrs) = symbols($io, $iom, values %fn);
    my %code;
    for my $k (keys %fn) {
        my $s = $sym->{$fn{$k}};
        if (!$s) { say_("  $k: symbol $fn{$k} missing"); push @problems, "IO80211Family: $fn{$k} missing"; next; }
        $code{$k} = fn_bytes($io, $iom, $addrs, $s->[1]);
    }
    my $e = $family ? $EXPECT{$family} : undef;
    # 1. interface -> private -> peer manager (getPeerManager: mov rax,[rdi+priv]; mov rax,[rax+pm])
    if (defined $code{pm} && $code{pm} =~ /\x48\x8b\x87(.{4})\x48\x8b\x40(.)/s) {
        my ($priv, $pm) = (unpack('V', $1), ord($2));
        my $ok = $e && $priv == $e->{priv} && $pm == $e->{pm};
        say_(sprintf('  peer manager chain: +0x%x -> +0x%x  %s', $priv, $pm, verdict($ok)));
        push @problems, sprintf('peer manager chain +0x%x -> +0x%x', $priv, $pm) unless $ok || !$family;
    } elsif (defined $code{pm}) { say_('  peer manager chain: pattern not found'); push @problems, 'getPeerManager changed'; }
    # 2./3. RX counter (inputPacket: mov rcx,[rbx+0x18]; inc dword [rcx+rx]) and TX (preQueuePacket: 2nd inc [rax+x])
    my ($rx, $tx);
    # The RX counter is the "inc dword [rcx+X]" followed within a few bytes by "inc dword [rcx+rax*4+X+4]" (the per-AC
    # counters right after it); a plain first increment can be another counter.
    if (defined $code{rx}) {
        while ($code{rx} =~ /\xff\x81(.{4})/sg) {
            my ($at, $v) = ($-[0], unpack('V', $1));
            if (index(substr($code{rx}, $at + 6, 12), "\xff\x84\x81" . pack('V', $v + 4)) >= 0) { $rx = $v; last; }
        }
    }
    if (defined $code{tx}) { my @inc = ($code{tx} =~ /\xff\x80(.{4})/sg); $tx = unpack('V', $inc[1]) if @inc >= 2; }
    if (defined $rx && defined $tx) {
        my $ok = $e && $rx == $e->{rx} && $tx == $e->{tx};
        say_(sprintf('  AWDL counters: RX +0x%x, TX +0x%x  %s', $rx, $tx, verdict($ok)));
        push @problems, sprintf('AWDL counters RX +0x%x TX +0x%x', $rx, $tx) unless $ok || !$family;
    } else { say_('  AWDL counters: pattern not found'); push @problems, 'AWDL counter code changed'; }
    # 4. MI request built by updatePrimaryPayloadMI (base -0x68: +0x04 ~0, +0x08 0xffff, +0x0c offset, +0x10 bitmap,
    #    +0x14 6, ioctl 0x95 or 0xe1)
    if (defined $code{mi}) {
        my @fp = (['base', '488d4598'], ['+0x04', 'c7459cffffffff'], ['+0x08', '66c745a0ffff'], ['+0x14', '66c745ac0600'],
                  ['now', 'c7458495000000'], ['auto', 'c74584e1000000'], ['bitmap', '44897da8'], ['offset', '44894da4'],
                  ['ioctl', 'c706c8692880']);
        my @miss = map { $_->[0] } grep { !has($code{mi}, $_->[1]) } @fp;
        say_('  MI request layout: ' . (@miss ? 'DIFFERENT (' . join(', ', @miss) . ')' : 'OK'));
        push @problems, 'MI request layout: ' . join(', ', @miss) if @miss;
    }
    # 5. UMI request built by sendUnicastMI: one of the two known shapes
    if (defined $code{umi}) {
        my $a = has($code{umi}, '4c8d7d9c') && has($code{umi}, '49894f2c') && has($code{umi}, '6641894f24') &&
                has($code{umi}, '6641c747100600');
        my $b = has($code{umi}, '4c8d7d98') && has($code{umi}, '668945c0') && has($code{umi}, '48894dc8') &&
                has($code{umi}, '66c745ac0600');
        say_('  UMI request layout: ' . ($a ? 'OK (shape A)' : $b ? 'OK (shape B)' : 'DIFFERENT'));
        push @problems, 'UMI request layout' unless $a || $b;
    }
    # 6. election RSSI threshold request: buffer at -0x38, threshold at +0x10, request 0x87
    if (defined $code{rssi}) {
        my $ok = has($code{rssi}, '488d4dc8') && (has($code{rssi}, '894110') || has($code{rssi}, '8945d8')) &&
                 ($code{rssi} =~ /[\xba\xbe]\x87\x00\x00\x00/s);
        say_('  RSSI threshold request: ' . ($ok ? 'OK' : 'DIFFERENT'));
        push @problems, 'RSSI threshold request' unless $ok;
    }
    # 7. IO80211AWDLProtocol vtable size (the driver also checks this at runtime)
    if (my $s = $sym->{$fn{vt}}) {
        my ($next) = grep { $_ > $s->[1] } @$addrs;
        if (defined $next) {
            my $slots = ($next - $s->[1]) / 8 - 3;
            my $ok = $e && $slots == $e->{slots};
            say_(sprintf('  IO80211AWDLProtocol vtable: %d slots  %s', $slots, verdict($ok)));
            push @problems, "IO80211AWDLProtocol has $slots slots" unless $ok || !$family;
        }
    }
}

# ---------------------------------------------------------------- tables and imports
if ($iom) {
    my (%byva, %names, $kcbase, $relocs);
    if ($opt{kext}) {
        image_symbols($io, $iom, \%byva, \%names);
        $relocs = ext_relocs($io, $iom);
        if ($opt{skywalk}) {
            my $sk = x86_slice(slurp($opt{skywalk}));
            my $skm = defined $sk ? macho($sk, 0) : undef;
            my %unused;
            image_symbols($sk, $skm, \%unused, \%names) if $skm;
        }
    } else {
        my $kc = macho($io, 0);
        for my $e (@{$kc->{entries}}) {
            my $m = macho($io, $e->[2]) or next;
            for my $sg (@{$m->{segs}}) { $kcbase = $sg->[1] if $sg->[2] && (!defined $kcbase || $sg->[1] < $kcbase); }
            image_symbols($io, $m, \%byva, \%names);
        }
    }
    my ($tsym, $taddrs) = symbols($io, $iom, @TABLES);
    my @details;
    say_('');
    say_('[IO80211 tables]');
    for my $t (@TABLES) {
        (my $short = $t) =~ s/^__ZTV\d+//;
        my $s = $tsym->{$t};
        if (!$s || $s->[0] ne $t) { say_("  $short: not present"); push @details, "== $short: not present"; next; }
        my ($next) = grep { $_ > $s->[1] } @$taddrs;
        my @n = vtable_names($io, $iom, $s->[1], defined $next ? $next - $s->[1] : 0, \%byva, $kcbase, $relocs);
        my $unknown = grep { /^\?/ } @n;
        say_(sprintf('  %-24s %4d slots, names %s%s', $short, scalar @n, substr(sha256_hex(join("\n", @n)), 0, 16),
                     $unknown ? " ($unknown unresolved)" : ''));
        push @details, sprintf('== %s: %d slots', $short, scalar @n), map { sprintf('%d %s', $_, $n[$_]) } 0 .. $#n;
    }
    # Every Apple symbol the ForbiddenItlwm kext for this family imports must exist here, or the kext can't load. On an
    # unsupported macOS the Sonoma kext, the oldest supported, is the comparison.
    my $against = $family || 'sonoma';
    if (my $blob = $IMPORTS{$against}) {
        my $list;
        gunzip(\decode_base64($blob) => \$list) or die "imports: $GunzipError\n";
        my @need = split /\n/, $list;
        # Loose files hold no kernel, and IOSkywalkFamily only with --skywalk: check what they can show.
        my @check = !$opt{kext} ? @need : grep { /IO80211|apple80211/ || ($opt{skywalk} && /Skywalk/) } @need;
        my @missing = grep { !$names{$_} } @check;
        say_(sprintf('  imports of the %s kext: %d of %d present%s', $against, @check - @missing, scalar @check,
                     $opt{kext} ? ' (IO80211/Skywalk symbols only, from loose files)' : ''));
        say_("    missing: $_") for @missing[0 .. ($#missing < 4 ? $#missing : 4)];
        push @problems, scalar(@missing) . " symbols the $against kext imports are missing" if @missing && $family && !$opt{kext};
        push @details, "== imports of the $against kext missing here: " . scalar @missing, @missing;
    }
    if ($opt{details}) {
        if (open(my $f, '>', $opt{details})) {
            print $f "ForbiddenItlwm build check v$VERSION details\n";
            print $f "macOS $osver ($osbuild), kernel $kernel\n" if $live;
            print $f "$_\n" for @details;
            close $f;
            say_("  details written to $opt{details}");
        } else { say_("  couldn't write $opt{details}"); }
    }
}

# ---------------------------------------------------------------- bluetoothd
say_('');
say_('[bluetoothd]');
my $bt = x86_slice(slurp($opt{bluetoothd}));
if (!defined $bt) {
    say_('  not readable');
    push @problems, "couldn't read bluetoothd";
} else {
    say_('  sha256 (x86_64) ' . substr(sha256_hex($bt), 0, 16));
    my $patchedSeen = 0;
    my %shape = (
        advertising        => qr/\x84\xc0\x0f\x84..\x00\x00\xe8....\x48\x8b\x08\x48\x89\xc7\xff\x91..\x00\x00\x41\x89\xc6/s,
        randomAddress      => qr/\x83\xb8..\x00\x00\x03\x77.\x31\xff\xe8..../s,
        extendedConnection => qr/\x0f\xb6\xbd.\xff\xff\xff\xe8..../s,
        dupFilter          => qr/\x41\xf6\xc6\x01\x75.\xf6\x85....\x01\x74.\x45\x31\xf6\xeb.\x41\xf6\xd6\x41\x80\xe6\x01\x45\x88\x75\x00\x45\x88\x75\x03|\x31\xc0\xeb.\x8b\x85....\x34\x01\x41?\x88.\x41?\x88.\x03/s,
    );
    $shape{scanning} = $shape{advertising};
    for my $site (qw(advertising scanning randomAddress extendedConnection dupFilter)) {
        my @hits;
        my $count = sub { my ($p) = @_; my ($n, $pos, $at) = (0, 0, -1);
                          while (($pos = index($bt, $p, $pos)) >= 0) { $n++; $at = $pos; $pos++; } return ($n, $at); };
        for my $k (grep { $_->[0] eq ($family || '') && $_->[1] eq $site } @KNOWN) {
            my ($find, $rep) = (pack('H*', $k->[3]), pack('H*', $k->[4]));
            my ($n, $at) = $count->($find);
            # With BTLEAdvFixup loaded, reading bluetoothd returns the pages it already patched.
            my ($pn, $pat) = $n ? (0, -1) : $count->($rep);
            if ($n == 1 || $pn == 1) {
                $at = $pat if $n != 1;
                push @hits, [$k->[2], $at, $n == 1 ? '' : ', already patched in memory by BTLEAdvFixup']
                    if int($at / 4096) == int(($at + length($find) - 1) / 4096);
                $patchedSeen = 1 if $n != 1;
            }
        }
        if (@hits) {
            say_(sprintf('  %-19s OK (%s at 0x%x%s)', $site, $hits[0][0], $hits[0][1], $hits[0][2]));
            next;
        }
        # No pattern of this build matched: show where code of the same shape is, so the site can be added.
        my @cand;
        while ($bt =~ /$shape{$site}/g) { push @cand, $-[0]; last if @cand >= 6; }
        say_(sprintf('  %-19s NO PATTERN (%d candidate%s by shape)', $site, scalar @cand, @cand == 1 ? '' : 's'));
        push @todo, "bluetoothd $site";
        for my $c (@cand) {
            my $from = $c >= 16 ? $c - 16 : 0;
            say_(sprintf('    0x%x: %s', $c, unpack('H*', substr($bt, $from, 64))));
        }
    }
    if ($live) {
        my $valid = system('/usr/bin/codesign', '-v', $opt{bluetoothd}) == 0;
        if ($valid) { say_('  Apple signature: valid'); }
        elsif ($patchedSeen) { say_('  Apple signature: not valid while BTLEAdvFixup patches it in memory (expected)'); }
        else { say_('  Apple signature: NOT VALID (modified system?)'); push @problems, 'bluetoothd signature not valid'; }
    }
}

# ---------------------------------------------------------------- summary
say_('');
if (!@problems && !@todo) {
    say_('RESULT: everything ForbiddenItlwm and BTLEAdvFixup rely on matches this build.');
} else {
    say_('RESULT: ' . join('; ', (map { "problem: $_" } @problems), (map { "needs a new pattern: $_" } @todo)));
}
print map { "$_\n" } @out;
exit((@problems || @todo) ? 1 : 0);
